+            <div class="d-flex justify-content-center align-items-center py-5">
+                <div class="spinner-border text-primary" role="status">
+                    <span class="visually-hidden">Loading…</span>
+                </div>
+                <span class="ms-2">Loading products…</span>
+            </div>
+        }
+        else if (result is not null)
+        {
+            @* Toolbar *@
+            <div class="toolbar d-flex justify-content-between align-items-center mb-3 p-2 border rounded bg-white">
+                <div class="d-flex align-items-center gap-2">
+                    <label class="form-label mb-0 small fw-semibold">Sort by:</label>
+                    <select class="form-select form-select-sm" style="width: auto;"
+                            @bind="sortBy" @bind:after="OnSortChanged">
+                        <option value="price_asc">Price: Low to High</option>
+                        <option value="price_desc">Price: High to Low</option>
+                        <option value="name_asc">Name: A–Z</option>
+                        <option value="rating_desc">Rating: Highest</option>
+                    </select>
+                </div>
+                <span class="text-muted small">
+                    @if (result.TotalCount > 0)
+                    {
+                        var first = (result.Page - 1) * result.PageSize + 1;
+                        var last = Math.Min(result.Page * result.PageSize, result.TotalCount);
+                        @($"Showing {first}–{last} of {result.TotalCount} products")
+                    }
+                    else
+                    {
+                        @("No products found")
+                    }
+                </span>
+            </div>
+
+            @if (result.Items.Count == 0)
+            {
+                <div class="text-center py-5">
+                    <h5 class="text-muted">No products match your filters</h5>
+                    <p class="text-muted">Try adjusting your filters or clearing them.</p>
+                    <button class="btn btn-outline-primary btn-sm" @onclick="ClearFilters">Clear Filters</button>
+                </div>
+            }
+            else
+            {
+                @* Product grid *@
+                <div class="product-grid">
+                    @foreach (var product in result.Items)
+                    {
+                        <ProductCard Product="product"
+                                     OnProductSelected="HandleProductSelected"
+                                     OnAddToCart="HandleAddToCart" />
+                    }
+                </div>
+
+                @* Pagination *@
+                @if (totalPages > 1)
+                {
+                    <nav aria-label="Product pagination" class="mt-4">
+                        <ul class="pagination justify-content-center">
+                            <li class="page-item @(currentPage <= 1 ? "disabled" : "")">
+                                <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
+                                        disabled="@(currentPage <= 1)">Previous</button>
+                            </li>
+                            @foreach (var p in GetPageNumbers())
+                            {
+                                <li class="page-item @(p == currentPage ? "active" : "")">
+                                    <button class="page-link" @onclick="() => GoToPage(p)">@p</button>
+                                </li>
+                            }
+                            <li class="page-item @(currentPage >= totalPages ? "disabled" : "")">
+                                <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
+                                        disabled="@(currentPage >= totalPages)">Next</button>
+                            </li>
+                        </ul>
+                    </nav>
+                }
+            }
+        }
+    </section>
+</div>
+
+@code {
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    // State
+    private List<string>? categories;
+    private PagedResult<Product>? result;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    // Filter inputs
+    private HashSet<string> selectedCategories = new();
+    private decimal? minPrice;
+    private decimal? maxPrice;
+    private bool inStockOnly;
+
+    // Paging & sorting
+    private string sortBy = "price_asc";
+    private int currentPage = 1;
+    private const int PageSize = 12;
+    private int totalPages => result is null ? 1 : Math.Max(1, (int)Math.Ceiling(result.TotalCount / (double)PageSize));
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadDataAsync();
+    }
+
+    private async Task LoadDataAsync()
+    {
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            if (categories is null)
+            {
+                categories = await ProductService.GetCategoriesAsync();
+            }
+
+            var filter = new ProductFilter(
+                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
+                MinPrice: minPrice,
+                MaxPrice: maxPrice,
+                InStockOnly: inStockOnly
+            );
+
+            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void ToggleCategory(string category, bool isChecked)
+    {
+        if (isChecked)
+            selectedCategories.Add(category);
+        else
+            selectedCategories.Remove(category);
+    }
+
+    private async Task ApplyFilters()
+    {
+        currentPage = 1;
+        await LoadDataAsync();
+    }
+
+    private async Task ClearFilters()
+    {
+        selectedCategories.Clear();
+        minPrice = null;
+        maxPrice = null;
+        inStockOnly = false;
+        currentPage = 1;
+        await LoadDataAsync();
+    }
+
+    private async Task OnSortChanged()
+    {
+        currentPage = 1;
+        await LoadDataAsync();
+    }
+
+    private async Task GoToPage(int page)
+    {
+        if (page < 1 || page > totalPages) return;
+        currentPage = page;
+        await LoadDataAsync();
+    }
+
+    private async Task RetryLoad() => await LoadDataAsync();
+
+    private async Task HandleProductSelected(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Placeholder for cart integration
+        return Task.CompletedTask;
+    }
+
+    private IEnumerable<int> GetPageNumbers()
+    {
+        const int maxVisible = 5;
+        int start = Math.Max(1, currentPage - maxVisible / 2);
+        int end = Math.Min(totalPages, start + maxVisible - 1);
+        start = Math.Max(1, end - maxVisible + 1);
+
+        for (int i = start; i <= end; i++)
+            yield return i;
+    }
+}
